\subsection{Field Equation for $\Psi$}

Variation with respect to $\Psi^\dagger$:

\begin{equation}
\frac{\delta S}{\delta\Psi^\dagger} = \sqrt{-g}\left[g^{\mu\nu}D_\mu D_\nu\Psi - \frac{\partial V}{\partial\Psi^\dagger} + \xi R\Psi\right] = 0
\end{equation}

For $V(\Psi) = \frac{\lambda}{4}(|\Psi|^2 - v^2)^2 + \frac{1}{2}m_{\text{eff}}^2|\Psi|^2$:

\begin{equation}
\square\Psi + m_{\text{eff}}^2\Psi + 2\xi R\Psi + \lambda(|\Psi|^2 - v^2)\Psi = 0
\end{equation}

This is the modified Klein-Gordon equation with non-minimal coupling.

\subsection{Dispersion Relation Derivation}

In flat spacetime ($R = 0$), expand around vacuum $\Psi = v + \phi$:

\begin{equation}
\square\phi + \left[m_{\text{eff}}^2 + 2\lambda v^2\right]\phi + \text{(higher orders)} = 0
\end{equation}

Plane wave ansatz $\phi \sim e^{i(k\cdot x - \omega t)}$ yields:

\begin{equation}
\omega^2 = k^2 + m_{\text{eff}}^2 + 2\lambda v^2
\end{equation}

In curved spacetime with non-minimal coupling:

\begin{equation}
\omega_n^2 = k_n^2 + m_{\text{eff}}^2 + 2\xi R + 2\lambda v^2
\end{equation}

For cavity modes with boundary conditions, $k_n = n\pi/L$:

\begin{equation}
\omega_n = \sqrt{\frac{n^2\pi^2}{L^2} + m_{\text{eff}}^2 + 2\xi R + 2\lambda v^2}

\subsection{Lagrangian Density}

The complete TGL Lagrangian unifies geometric (Einstein-Hilbert), kinetic ($\Psi$ dynamics), interaction (non-minimal coupling), and gauge sectors:

\begin{equation}
\mathcal{L}_{\text{TGL}} = \frac{c^4}{16\pi G}\sqrt{-g}R + \frac{1}{2}\sqrt{-g}g^{\mu\nu}D_\mu\Psi^\dagger D_\nu\Psi - \sqrt{-g}V(\Psi) + \xi\sqrt{-g}R|\Psi|^2 - \frac{1}{4}F_{\mu\nu}F^{\mu\nu}
\end{equation}

Where:

\begin{itemize}
    \item $D_\mu = \nabla_\mu - ieA_\mu$: gauge-covariant derivative (U(1) local symmetry)
    \item $V(\Psi)$: self-interaction potential (Higgs-like)
    \item $\xi$: non-minimal coupling parameter
    \item $m_{\text{eff}}$: effective permanence mass
\end{itemize}

\subsection{Field Equations}

From $\delta S/\delta\Psi = 0$:

\begin{equation}
\Box\Psi + m_{\text{eff}}^2\Psi + 2\xi R\Psi + V'(\Psi) = 0
\end{equation}

Modified Einstein equations:

\begin{equation}
G_{\mu\nu} + \Lambda g_{\mu\nu} = 8\pi G(T_{\mu\nu}^{\text{matter}} + T_{\mu\nu}^\Psi)
\end{equation}

Where the $\Psi$-sector energy-momentum tensor includes the non-minimal coupling:

\begin{multline}
T_{\mu\nu}^\Psi = D_\mu\Psi^\dagger D_\nu\Psi - \frac{1}{2}g_{\mu\nu}g^{\alpha\beta}D_\alpha\Psi^\dagger D_\beta\Psi - g_{\mu\nu}V(\Psi) \\
+ 2\xi\left(G_{\mu\nu}|\Psi|^2 - \nabla_\mu\nabla_\nu|\Psi|^2 + g_{\mu\nu}\Box|\Psi|^2\right)

Expand the field in cavity normal modes with boundary conditions (mirrors/BNI):

\begin{equation}
\hat{\Psi}(x,t) = \sum_n \frac{1}{\sqrt{2\omega_n}}\left(\hat{a}_n u_n(x)e^{-i\omega_n t} + \hat{a}_n^\dagger u_n^*(x)e^{i\omega_n t}\right)
\end{equation}

Where $u_n$ satisfies:

\begin{equation}
\left[-\frac{1}{2}\nabla^2 + V(|\Psi|^2) + \xi R\right]u_n = \omega_n^2 u_n
\end{equation}

With Dirichlet boundary conditions: $u_n|_{\partial V} = 0$

Commutation relations:

\begin{equation}
[\hat{a}_n, \hat{a}_m^\dagger] = \delta_{nm}
\end{equation}

\subsection{Hamiltonian}

\begin{equation}
\hat{H}_{\text{TGL}} = \sum_n \hbar\omega_n\left(\hat{a}_n^\dagger\hat{a}_n + \frac{1}{2}\right) + \hat{H}_{\text{grav}} + \hat{H}_{\text{int}}
\end{equation}

Interaction term:

\begin{equation}
\hat{H}_{\text{int}} = \int d^3x\sqrt{h}\left[\xi R\hat{\Psi}^\dagger\hat{\Psi} + \frac{\lambda}{4}(\hat{\Psi}^\dagger\hat{\Psi})^2\right]

\subsection{Dispersion Relation}

\textbf{Photon (propagating):}

\begin{equation}
\omega = c|k|
\end{equation}

\textbf{Psion (stationary in cavity):}

\begin{equation}
\omega_n^2 = k_n^2 + m_{\text{eff}}^2 + 2\xi R
\end{equation}

\textbf{Key distinction:} Even when $k_n \rightarrow 0$ (zero-mode/``mirror mode''), $\omega_n$ remains finite due to $m_{\text{eff}}$ and $R$ coupling $\rightarrow$ \textbf{maximal permanence} (memory storage).

\section*{Resumo}
Este capítulo fixa a leitura TGL da ``água escura'' como um \emph{superfluido escuro} (SFDM) descrito por um campo complexo $\Psi$. Construímos o modelo efetivo, destacamos a faixa de \textbf{contração sob excitação} (``anomalia da água'') como \emph{expansão térmica negativa}, definimos predições observacionais, \emph{kill-switches} e o \textbf{pipeline de calibração} conectado às Runs 1--3.

\section{Modelo Efetivo (hidrodinâmica de Madelung)}
\subsection{Ação}
Adotamos, em unidades com $c=1$ e explicitando $G$ e $h$ quando necessário,
\begin{equation}
S=\!\int\!\sqrt{-g}\,\Big[\frac{\Mpl^2}{2}R - \frac{Z(|\Psi|)}{2}|\nabla\Psi|^2 - V(|\Psi|) - \lambda J_\mu J^\mu + \xi |\Psi|^2 R + \eta |\Psi|^2 F_{\mu\nu}F^{\mu\nu} + \kappa\,\theta\, F\tilde F \Big],
\end{equation}
onde $\Psi=\sqrt{\rho}\,e^{i\theta}$, $J_\mu=\rho\,\partial_\mu\theta$ e $F_{\mu\nu}$ é o campo eletromagnético efetivo do banho.

\subsection{Potencial e parâmetros}
Tomamos
\begin{equation}
V(|\Psi|)=\frac{m_*^2}{2}\,|\Psi|^2 + \frac{g_4}{4}\,|\Psi|^4 + \frac{g_6}{6}\,|\Psi|^6,
\end{equation}
com $m_*$ a escala de massa efetiva, $g_4$ atraente (pode ser negativo) e $g_6>0$ estabilizando o condensado.

\subsection{Hidrodinâmica}
Na decomposição de Madelung,
\begin{align}
&\partial_t \rho + \nabla\!\cdot(\rho\,\mathbf{v})=0,\qquad \mathbf{v}=\nabla\theta,\\
&\partial_t \theta + \frac{(\nabla\theta)^2}{2} + \mu(\rho) - \frac{1}{2}\frac{\nabla^2\sqrt{\rho}}{\sqrt{\rho}} + \Phi_{\rm grav} + \text{cpl. EM}=0,
\end{align}
onde $\mu(\rho)=\partial_\rho V_{\rm eff}$ e o termo de ``pressão quântica'' atua como \emph{tensão superficial efetiva}. Assumindo uma EoS politrópica $P=K\,\rho^\gamma$, o som local satisfaz $c_s^2=\partial P/\partial\rho=\gamma K \rho^{\gamma-1}$.

\section{Acoplamento ao banho EM e cinética TGL}
Introduzimos a ponte TGL
\begin{equation}
\frac{h\nu_*}{G}\,t_{\mathrm{fix}} \;=\; E_g(L)=\xi\,C\,G\,\rho^2 L^5,
\end{equation}
e definimos $\nu_*$ e $t_{\mathrm{fix}}$ como funcionais do banho EM através de $(\eta,\kappa)$ e do histórico astrofísico (AGN/starburst). Em ambientes com \emph{banho forte}, $t_{\mathrm{fix}}$ efetivo encurta e o vínculo se intensifica (amarração maior).

\section{Régua de transposição e invariante}
Em média inter-objetos,
\begin{equation}
L_*(\rho)=\sqrt{\frac{\varepsilon_*}{\xi C G\,\rho\, m_*}}\,,\qquad
K_0^{(\mathrm{SFDM})} = L_*\sqrt{\rho}=\sqrt{\frac{\varepsilon_*}{\xi C G m_*}}.
\end{equation}
A predição TGL é um \emph{slope} $-1/2$ em $\log L$ vs. $\log\rho$ entre objetos; o recalibre de $K_0$ adapta os valores absolutos sem alterar o \emph{slope}.

\textbf{Definition:} Gravitons are not particles but \textit{operators} mediating the exit of light from free propagation into localized mass.

\begin{equation}
g = \oint_{\partial V} N \cdot \frac{\partial \gamma}{\partial t} , d\Sigma
\end{equation}

Where:
\begin{itemize}
\item $N$: Naming operator (assigns identity).
\item $\partial \gamma / \partial t$: Temporal derivative of photon field (rate of change).
\item $\partial V$: Boundary of volume where collapse occurs.
\end{itemize}

\textbf{Properties:}
\begin{itemize}
\item Not a particle: Graviton is a \textit{process} (exit of light).
\item Induces mass: $m = g \cdot |\gamma|^2 / c^2$.

\subsubsection{Mass-Energy Relation}

Particle mass arises from trapped light:

\begin{equation}
mc^2 = \int_V g \cdot |\gamma|^2 , dV
\end{equation}

\textbf{Interpretation:} Mass is photonic energy prevented from escaping volume $V$ by graviton operator $g$.

Special case (standing wave):

\begin{equation}
mc^2 = h\nu_{\text{standing}} = g \cdot N \cdot |\Psi|^2
\end{equation}

Where $N$ is the particle’s identity (name) and $\Psi$ its wavefunction.
